package routing

import (
	"fmt"
	"strings"

	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
)

// Capabilities describes what a (harness, provider, model) tuple can do.
// Populated from harness config + catalog metadata + provider discovery.
type Capabilities struct {
	ContextWindow      int      // resolved tokens; 0 = unknown
	SupportsTools      bool     // supports tool/function calling
	SupportsStreaming  bool     // supports streaming responses
	SupportedReasoning []string // supported public reasoning values
	MaxReasoningTokens int      // 0 means numeric reasoning is unsupported/unknown
	SupportedPerms     []string // {"safe","supervised","unrestricted"} subset
	ExactPinSupport    bool     // accepts exact concrete model pins
	SupportedModels    []string // nil = no static allow-list
}

// HasReasoning returns true if the candidate supports the requested reasoning
// value. Empty, auto, off, and numeric 0 impose no requirement.
func (c Capabilities) HasReasoning(value string) bool {
	policy, err := reasoning.ParseString(value)
	if err != nil {
		return false
	}
	switch policy.Kind {
	case reasoning.KindUnset, reasoning.KindAuto, reasoning.KindOff:
		return true
	case reasoning.KindTokens:
		return c.MaxReasoningTokens > 0 && policy.Tokens <= c.MaxReasoningTokens
	case reasoning.KindNamed:
		for _, supported := range c.SupportedReasoning {
			normalized, err := reasoning.Normalize(supported)
			if err == nil && normalized == policy.Value {
				return true
			}
		}
		return false
	default:
		return false
	}
}

// HasPermissions returns true if the candidate supports the requested level.
// An empty permission level always returns true.
func (c Capabilities) HasPermissions(perm string) bool {
	if perm == "" {
		return true
	}
	for _, p := range c.SupportedPerms {
		if strings.EqualFold(p, perm) {
			return true
		}
	}
	return false
}

// HasModel returns true when the exact model pin is within the static
// harness allow-list. A nil allow-list means the harness delegates validation
// to provider-side model checks.
func (c Capabilities) HasModel(model string) bool {
	if c.SupportedModels == nil || model == "" {
		return true
	}
	for _, supported := range c.SupportedModels {
		if supported == model {
			return true
		}
	}
	return false
}

// CheckGating applies all capability gates against a request and returns
// the first failure reason (free-form string for diagnostics) plus the
// typed FilterReason category for the failure. Returns ("", FilterReasonEligible)
// when all gates pass.
//
// The typed return is the authoritative classification — callers must not
// re-classify by parsing the string. The string is for human-readable
// diagnostics only.
//
// Fixes ddx-4817edfd subtree: pre-dispatch capability check covering
// context window, tool support, effort, permissions.
func CheckGating(cap Capabilities, req Request) (string, FilterReason) {
	// Context window gating: if the request declares prompt size or an effort
	// that implies a minimum context, reject candidates that can't fit.
	minCtx := req.MinContextWindow()
	if minCtx > 0 && cap.ContextWindow > 0 && cap.ContextWindow < minCtx {
		return fmt.Sprintf("context window %d < required %d", cap.ContextWindow, minCtx), FilterReasonContextTooSmall
	}

	// Tool-calling support gating.
	if req.RequiresTools && !cap.SupportsTools {
		return "tool calling not supported", FilterReasonNoToolSupport
	}

	if !cap.HasReasoning(req.Reasoning) {
		return fmt.Sprintf("reasoning %q not supported", req.Reasoning), FilterReasonReasoningUnsupported
	}

	// Permissions support gating.
	if !cap.HasPermissions(req.Permissions) {
		return fmt.Sprintf("permissions %q not supported", req.Permissions), FilterReasonScoredBelowTop
	}

	if req.Model != "" && !cap.HasModel(req.Model) {
		return "model not in harness allow-list", FilterReasonScoredBelowTop
	}

	// Exact-pin gating: an explicit Model field requires ExactPinSupport.
	if req.Model != "" && req.ModelRef == "" && !cap.ExactPinSupport {
		return "exact model pin not supported", FilterReasonScoredBelowTop
	}

	return "", FilterReasonEligible
}

// CheckPowerEligibility applies catalog-power gates for unpinned automatic
// routing. Exact model pins bypass this gate so callers can intentionally run
// a discovered model that is missing catalog power or marked exact-pin-only.
func CheckPowerEligibility(lookup func(string) (ModelEligibility, bool), model string, req Request) (string, FilterReason) {
	if req.Model != "" || lookup == nil {
		return "", FilterReasonEligible
	}
	if model == "" {
		return "model has no catalog power metadata", FilterReasonPowerMissing
	}
	eligibility, ok := lookup(model)
	if !ok {
		if req.MinPower > 0 || req.MaxPower > 0 {
			return fmt.Sprintf("model %q has no catalog power metadata", model), FilterReasonPowerMissing
		}
		return "", FilterReasonEligible
	}
	if eligibility.ExactPinOnly {
		return fmt.Sprintf("model %q is exact-pin-only", model), FilterReasonExactPinOnly
	}
	if !eligibility.AutoRoutable {
		if eligibility.Power <= 0 {
			return fmt.Sprintf("model %q has no catalog power metadata", model), FilterReasonPowerMissing
		}
		return fmt.Sprintf("model %q is not auto-routable", model), FilterReasonNotAutoRoutable
	}
	if req.MinPower > 0 && eligibility.Power < req.MinPower {
		return fmt.Sprintf("model %q power %d < min_power %d", model, eligibility.Power, req.MinPower), FilterReasonBelowMinPower
	}
	if req.MaxPower > 0 && eligibility.Power > req.MaxPower {
		return fmt.Sprintf("model %q power %d > max_power %d", model, eligibility.Power, req.MaxPower), FilterReasonAboveMaxPower
	}
	return "", FilterReasonEligible
}

// resolveRequestReasoning returns a copy of req with Reasoning resolved to the
// catalog's surface_policy reasoning_default for the request's profile/surface
// when the request asks for Reasoning=auto. This must run before CheckGating
// so candidates that only support a different reasoning level (e.g. an
// off-only variant under a profile whose surface default is "high") are
// correctly disqualified by the capability gate. Other Reasoning values
// (unset, off, named, numeric) are left untouched, preserving the existing
// behavior of those code paths.
func resolveRequestReasoning(req Request, surface string, resolver func(profile, surface string) (string, bool)) Request {
	if resolver == nil || req.Profile == "" {
		return req
	}
	policy, err := reasoning.ParseString(req.Reasoning)
	if err != nil || policy.Kind != reasoning.KindAuto {
		return req
	}
	resolved, ok := resolver(req.Profile, surface)
	if !ok || resolved == "" {
		return req
	}
	out := req
	out.Reasoning = resolved
	return out
}

package fizeau

import (
	"strings"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/routehealth"
)

const stickyRouteLeaseTTL = routehealth.DefaultLeaseTTL

func (s *service) routeLeaseStore() *routehealth.LeaseStore {
	if s.routeLeases == nil {
		s.routeLeases = routehealth.NewLeaseStore()
	}
	return s.routeLeases
}

func (s *service) applyStickyRouteLease(stickyKey string, decision *RouteDecision) {
	if s == nil || decision == nil || strings.TrimSpace(stickyKey) == "" {
		return
	}
	if decision.Harness != "agent" || decision.Provider == "" {
		return
	}

	now := time.Now().UTC()
	store := s.routeLeaseStore()
	baseProvider, _, _ := splitEndpointProviderRef(decision.Provider)
	if baseProvider == "" {
		baseProvider = decision.Provider
	}
	if baseProvider == "" || decision.Model == "" {
		return
	}

	key := routehealth.NormalizeLeaseKey(stickyKey, baseProvider, decision.Model)
	if lease, ok := store.Live(now, key); ok {
		if candidate, found := stickyLeaseCandidate(decision.Candidates, decision.Harness, baseProvider, decision.Model, lease.Endpoint); found && candidate.Eligible {
			store.Acquire(now, stickyRouteLeaseTTL, key, baseProvider, lease.Endpoint, decision.Model)
			decision.Provider = candidate.Provider
			decision.Endpoint = candidate.Endpoint
			return
		}
		reason := "endpoint disappeared"
		if candidate, found := stickyLeaseCandidate(decision.Candidates, decision.Harness, baseProvider, decision.Model, lease.Endpoint); found {
			reason = candidate.Reason
			if reason == "" {
				reason = "sticky endpoint became ineligible"
			}
		} else if candidate, found := stickyLeaseAnyEndpoint(decision.Candidates, decision.Harness, baseProvider, lease.Endpoint); found {
			reason = candidate.Reason
			if reason == "" {
				reason = "sticky endpoint became ineligible"
			}
		}
		store.Invalidate(now, key, reason)
	}

	candidate, found := stickyLeasePick(decision.Candidates, decision.Harness, baseProvider, decision.Model, store.LeaseCounts(now, baseProvider, decision.Model))
	if !found || !candidate.Eligible {
		return
	}
	chosenEndpoint := candidate.Endpoint
	if chosenEndpoint == "" {
		_, chosenEndpoint, _ = splitEndpointProviderRef(candidate.Provider)
	}
	if chosenEndpoint == "" {
		chosenEndpoint = candidate.Provider
	}
	store.Acquire(now, stickyRouteLeaseTTL, key, baseProvider, chosenEndpoint, decision.Model)
	decision.Provider = candidate.Provider
	decision.Endpoint = candidate.Endpoint
}

func stickyLeasePick(candidates []RouteCandidate, harness, provider, model string, counts map[string]int) (RouteCandidate, bool) {
	var chosen RouteCandidate
	found := false
	for _, candidate := range candidates {
		if !candidate.Eligible || candidate.Harness != harness || candidate.Model != model {
			continue
		}
		baseProvider, _, _ := splitEndpointProviderRef(candidate.Provider)
		if baseProvider == "" {
			baseProvider = candidate.Provider
		}
		if baseProvider != provider {
			continue
		}
		if candidate.Endpoint == "" && candidate.Provider == "" {
			continue
		}
		if !found {
			chosen = candidate
			found = true
			continue
		}
		leftCount := counts[endpointOf(candidate)]
		rightCount := counts[endpointOf(chosen)]
		if leftCount != rightCount {
			if leftCount < rightCount {
				chosen = candidate
			}
			continue
		}
		if candidate.Score != chosen.Score {
			if candidate.Score > chosen.Score {
				chosen = candidate
			}
			continue
		}
		if endpointOf(candidate) < endpointOf(chosen) {
			chosen = candidate
		}
	}
	return chosen, found
}

func stickyLeaseCandidate(candidates []RouteCandidate, harness, provider, model, endpoint string) (RouteCandidate, bool) {
	for _, candidate := range candidates {
		if !candidate.Eligible || candidate.Harness != harness || candidate.Model != model {
			continue
		}
		baseProvider, candidateEndpoint, _ := splitEndpointProviderRef(candidate.Provider)
		if baseProvider == "" {
			baseProvider = candidate.Provider
		}
		if baseProvider != provider {
			continue
		}
		if candidateEndpoint == "" {
			candidateEndpoint = candidate.Endpoint
		}
		if candidateEndpoint == endpoint {
			return candidate, true
		}
	}
	return RouteCandidate{}, false
}

func stickyLeaseAnyEndpoint(candidates []RouteCandidate, harness, provider, endpoint string) (RouteCandidate, bool) {
	for _, candidate := range candidates {
		if candidate.Harness != harness {
			continue
		}
		baseProvider, candidateEndpoint, _ := splitEndpointProviderRef(candidate.Provider)
		if baseProvider == "" {
			baseProvider = candidate.Provider
		}
		if baseProvider != provider {
			continue
		}
		if candidateEndpoint == "" {
			candidateEndpoint = candidate.Endpoint
		}
		if candidateEndpoint == endpoint {
			return candidate, true
		}
	}
	return RouteCandidate{}, false
}

func endpointOf(candidate RouteCandidate) string {
	if _, endpoint, ok := splitEndpointProviderRef(candidate.Provider); ok && endpoint != "" {
		return endpoint
	}
	return candidate.Endpoint
}

}

// buildRoutingInputs assembles routing.Inputs from the service's registry
// and ServiceConfig. When the service has a catalog cache attached (v0.9.2+),
// each configured provider's ProviderEntry is populated with DiscoveredIDs
// from the cache's live /v1/models probe, so routing.FuzzyMatch matches the
// request against IDs the server actually serves rather than the configured
// default-model string.
//
// ctx is used for cache probes with a short deadline; the cache's
// stale-while-revalidate flow makes most calls non-blocking.
func (s *service) buildRoutingInputs(ctx context.Context) routing.Inputs {
	return s.buildRoutingInputsWithCatalog(ctx, serviceRoutingCatalog())
}

func (s *service) buildRoutingInputsWithCatalog(ctx context.Context, cat *modelcatalog.Catalog) routing.Inputs {
	statuses := s.registry.Discover()
	statusByName := make(map[string]harnesses.HarnessStatus, len(statuses))
	for _, st := range statuses {
		statusByName[st.Name] = st
	}

	var entries []routing.HarnessEntry
	for _, name := range s.registry.Names() {
		cfg, ok := s.registry.Get(name)
		if !ok {
			continue
		}
		st := statusByName[name]
		entry := routing.HarnessEntry{
			Name:                name,
			Surface:             cfg.Surface,
			CostClass:           cfg.CostClass,
			IsLocal:             cfg.IsLocal,
			IsSubscription:      cfg.IsSubscription,
			IsHTTPProvider:      cfg.IsHTTPProvider,
			AutoRoutingEligible: cfg.AutoRoutingEligible,
			TestOnly:            cfg.TestOnly,
			ExactPinSupport:     cfg.ExactPinSupport,
			DefaultModel:        cfg.DefaultModel,
			SupportedModels:     subprocessHarnessModelIDs(name, cfg),
			SupportedReasoning:  supportedReasoning(cfg),
			MaxReasoningTokens:  cfg.MaxReasoningTokens,
			SupportedPerms:      supportedPermissions(cfg),
			SupportsTools:       true, // all builtin harnesses support tools today
			Available:           st.Available,
			QuotaOK:             true,
			QuotaTrend:          routing.QuotaTrendUnknown,
			// SubscriptionOK defaults to true and is refined by subscription
			// harness quota caches below.
			SubscriptionOK: true,
		}
		if name == "agent" && s.opts.ServiceConfig == nil {
			entry.AutoRoutingEligible = false
		}

		if qs, ok := subscriptionQuotaForHarness(name, time.Now()); ok {
			entry.QuotaOK = qs.OK
			entry.QuotaStale = qs.Present && !qs.Fresh
			entry.SubscriptionOK = qs.OK
			entry.QuotaPercentUsed = qs.PercentUsed
			entry.QuotaTrend = qs.Trend
			entry.QuotaReason = qs.Reason
		}

		// Native "agent" harness: enumerate live configured provider endpoints.
		if name == "agent" && s.opts.ServiceConfig != nil {
			for _, pname := range s.opts.ServiceConfig.ProviderNames() {
				pcfg, ok := s.opts.ServiceConfig.Provider(pname)
				if !ok {
					continue
				}
				entry.Providers = append(entry.Providers, s.liveProviderEntries(ctx, pname, pcfg, cat)...)
			}
			// Tool support for the agent harness is per-(provider, model);
			// the harness-level baseline is whether ANY provider supports
			// tools. Engine OR-combines harness and provider SupportsTools
			// so this lets a per-model no_tools catalog flag actually fire
			// the RequiresTools gate when every provider's resolved model
			// is no-tools.
			if len(entry.Providers) > 0 {
				entry.SupportsTools = anyProviderSupportsTools(entry.Providers)
			} else {
				entry.Available = false
			}
		}
		s.applySubscriptionRoutingCost(&entry, cat)
		entries = append(entries, entry)
	}
	successRate, latencyMS := s.routeMetricSignals(time.Now(), s.routeAttemptTTL())
	return routing.Inputs{
		Harnesses:                   entries,
		ProviderSuccessRate:         successRate,
		ObservedLatencyMS:           latencyMS,
		ProviderQuotaExhaustedUntil: s.providerQuotaExhaustedUntil(time.Now()),
		CatalogResolver:             serviceRoutingCatalogResolver(cat),
		CatalogCandidatesResolver:   serviceRoutingCatalogCandidatesResolver(cat),
		ModelEligibility:            serviceRoutingModelEligibility(cat),
		ReasoningResolver:           serviceRoutingReasoningResolver(cat),
	}
}

// providerQuotaExhaustedUntil snapshots the per-provider quota state machine
// at the given instant for the routing engine. Returns nil when no provider
// is currently in quota_exhausted state, which keeps the routing path
// allocation-free in the common case.
func (s *service) providerQuotaExhaustedUntil(now time.Time) map[string]time.Time {
	if s == nil || s.providerQuota == nil {
		return nil
	}
	return s.providerQuota.ExhaustedAt(now)
}

// startQuotaRecoveryProbeLoop spawns the goroutine that periodically probes
// quota_exhausted providers and either restores them to available or extends
// their retry_after with bounded backoff. The goroutine is tied to
// QuotaRefreshContext (or context.Background()) so server callers can cancel
// it on shutdown.
func (s *service) startQuotaRecoveryProbeLoop() {
	if s == nil || s.providerQuota == nil {
		return
	}
	ctx := s.opts.QuotaRefreshContext
	if ctx == nil {
		ctx = context.Background()
	}
	probe := s.quotaRecoveryProber()
	if probe == nil {
		return
	}
	go runQuotaRecoveryProbeLoop(ctx, s.providerQuota, probe, defaultQuotaRecoveryFallbackInterval, nil, nil)
}

// quotaRecoveryProber returns the QuotaRecoveryProber used by the recovery
// loop. It looks up the provider entry in ServiceConfig and reuses the same
// probeProviderStatus the HealthCheck endpoint uses; a "connected" status
// counts as recovery, anything else is reported as a probe failure so the
// retry_after gets extended with backoff.
func (s *service) quotaRecoveryProber() QuotaRecoveryProber {
	sc := s.opts.ServiceConfig
	if sc == nil {
		return nil
	}
	return func(ctx context.Context, name string) error {
		entry, ok := sc.Provider(name)
		if !ok {
			return fmt.Errorf("provider %q not found", name)
		}
		probeCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
		defer cancel()
		probe := probeProviderStatus(probeCtx, entry, time.Now().UTC())
		if probe.status == "connected" {
			return nil
		}
		if probe.detail != "" {
			return fmt.Errorf("%s", probe.detail)
		}
		return fmt.Errorf("%s", probe.status)
	}
}

