package routehealth

import (
	"fmt"
	"strings"
	"sync"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/routing"
)

// DefaultCooldown is the process-local route-attempt TTL used when service
// configuration does not provide a health cooldown.
const DefaultCooldown = 30 * time.Second

// Attempt records availability feedback for one routed attempt.
type Attempt struct {
	Harness   string
	Provider  string
	Model     string
	Endpoint  string
	Status    string
	Reason    string
	Error     string
	Duration  time.Duration
	Timestamp time.Time
}

// Key is the normalized route-attempt identity.
type Key struct {
	Harness  string
	Provider string
	Model    string
	Endpoint string
}

// Record is an active route-attempt failure.
type Record struct {
	Key        Key
	Status     string
	Reason     string
	Error      string
	Duration   time.Duration
	RecordedAt time.Time
}

type metricRecord struct {
	attempts      int
	successes     int
	totalDuration time.Duration
	recordedAt    time.Time
}

// Store owns process-local route-attempt failure feedback and reliability
// metrics. It is safe for concurrent use.
type Store struct {
	mu       sync.RWMutex
	failures map[Key]Record
	metrics  map[Key]metricRecord
}

// NewStore returns an empty route-health store.
func NewStore() *Store {
	return &Store{
		failures: make(map[Key]Record),
		metrics:  make(map[Key]metricRecord),
	}
}

// RecordAttempt records availability feedback. Success clears matching active
// failures; non-success records an active failure and updates metrics.
func (s *Store) RecordAttempt(attempt Attempt) error {
	key := NormalizeKey(attempt)
	if key.Harness == "" && key.Provider == "" {
		return fmt.Errorf("route attempt requires harness or provider")
	}
	status := strings.ToLower(strings.TrimSpace(attempt.Status))
	if status == "" {
		return fmt.Errorf("route attempt status is required")
	}
	recordedAt := attempt.Timestamp
	if recordedAt.IsZero() {
		recordedAt = time.Now()
	}
	recordedAt = recordedAt.UTC()

	s.mu.Lock()
	defer s.mu.Unlock()
	if s.failures == nil {
		s.failures = make(map[Key]Record)
	}
	if s.metrics == nil {
		s.metrics = make(map[Key]metricRecord)
	}
	s.recordMetricLocked(key, Succeeded(status), attempt.Duration, recordedAt)

	if Succeeded(status) {
		s.clearFailuresLocked(key)
		return nil
	}

	s.failures[key] = Record{
		Key:        key,
		Status:     status,
		Reason:     strings.TrimSpace(attempt.Reason),
		Error:      strings.TrimSpace(attempt.Error),
		Duration:   attempt.Duration,
		RecordedAt: recordedAt,
	}
	return nil
}

func (s *Store) recordMetricLocked(key Key, success bool, duration time.Duration, recordedAt time.Time) {
	record := s.metrics[key]
	record.attempts++
	if success {
		record.successes++
	}
	if duration > 0 {
		record.totalDuration += duration
	}
	record.recordedAt = recordedAt
	s.metrics[key] = record
}

// NormalizeKey returns the normalized route-attempt key for attempt.
func NormalizeKey(attempt Attempt) Key {
	return Key{
		Harness:  strings.TrimSpace(attempt.Harness),
		Provider: strings.TrimSpace(attempt.Provider),
		Model:    strings.TrimSpace(attempt.Model),
		Endpoint: strings.TrimSpace(attempt.Endpoint),
	}
}

// Succeeded reports whether status is a success spelling.
func Succeeded(status string) bool {
	switch status {
	case "success", "ok", "succeeded":
		return true
	default:
		return false
	}
}

func (s *Store) clearFailuresLocked(key Key) {
	for existing := range s.failures {
		if KeysMatch(existing, key) {
			delete(s.failures, existing)
		}
	}
}

// KeysMatch reports whether existing satisfies every non-empty query field.
func KeysMatch(existing, query Key) bool {
	if query.Harness != "" && existing.Harness != query.Harness {
		return false
	}
	if query.Provider != "" && existing.Provider != query.Provider {
		return false
	}
	if query.Model != "" && existing.Model != query.Model {
		return false
	}
	if query.Endpoint != "" && existing.Endpoint != query.Endpoint {
		return false
	}
	return true
}

// ActiveAttempts returns active failure records and removes expired records
// from the store.
func (s *Store) ActiveAttempts(now time.Time, ttl time.Duration) []Record {
	if s == nil {
		return nil
	}
	if ttl <= 0 {
		ttl = DefaultCooldown
	}
	if now.IsZero() {
		now = time.Now()
	}
	now = now.UTC()

	s.mu.Lock()
	defer s.mu.Unlock()
	if len(s.failures) == 0 {
		return nil
	}
	out := make([]Record, 0, len(s.failures))
	for key, record := range s.failures {
		if !record.RecordedAt.Add(ttl).After(now) {
			delete(s.failures, key)
			continue
		}
		out = append(out, record)
	}
	return out
}

// MetricSignals returns provider/model success-rate and latency maps suitable
// for routing inputs.
func (s *Store) MetricSignals(now time.Time, ttl time.Duration) (map[string]float64, map[string]float64) {
	if s == nil {
		return nil, nil
	}
	if ttl <= 0 {
		ttl = DefaultCooldown
	}
	if now.IsZero() {
		now = time.Now()
	}
	now = now.UTC()

	s.mu.RLock()
	defer s.mu.RUnlock()
	if len(s.metrics) == 0 {
		return nil, nil
	}
	successRate := make(map[string]float64, len(s.metrics))
	latencyMS := make(map[string]float64, len(s.metrics))
	for key, record := range s.metrics {
		if record.attempts <= 0 {
			continue
		}
		if !record.recordedAt.IsZero() && !record.recordedAt.Add(ttl).After(now) {
			continue
		}
		metricKey := ProviderModelKey(key)
		successRate[metricKey] = float64(record.successes) / float64(record.attempts)
		if record.totalDuration > 0 {
			latencyMS[metricKey] = float64(record.totalDuration.Milliseconds()) / float64(record.attempts)
		}
	}
	return successRate, latencyMS
}

// ProviderModelKey returns the routing provider/model metric key for key.
func ProviderModelKey(key Key) string {
	return routing.ProviderModelKey(key.Provider, key.Endpoint, key.Model)

package fizeau

import (
	"context"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/routehealth"
)

const defaultRouteAttemptCooldown = routehealth.DefaultCooldown

func (s *service) RecordRouteAttempt(_ context.Context, attempt RouteAttempt) error {
	if s == nil {
		s = &service{}
	}
	return s.routeHealthStore().RecordAttempt(routehealth.Attempt{
		Harness:   attempt.Harness,
		Provider:  attempt.Provider,
		Model:     attempt.Model,
		Endpoint:  attempt.Endpoint,
		Status:    attempt.Status,
		Reason:    attempt.Reason,
		Error:     attempt.Error,
		Duration:  attempt.Duration,
		Timestamp: attempt.Timestamp,
	})
}

func (s *service) routeHealthStore() *routehealth.Store {
	if s.routeHealth == nil {
		s.routeHealth = routehealth.NewStore()
	}
	return s.routeHealth
}

func (s *service) activeRouteAttempts(now time.Time, ttl time.Duration) []routehealth.Record {
	if s == nil || s.routeHealth == nil {
		return nil
	}
	return s.routeHealth.ActiveAttempts(now, ttl)
}

func routeAttemptCooldown(record routehealth.Record, ttl time.Duration) *CooldownState {
	if ttl <= 0 {
		ttl = defaultRouteAttemptCooldown
	}
	reason := record.Reason
	if reason == "" {
		reason = "route_attempt_failure"
	}
	return &CooldownState{
		Reason:      reason,
		Until:       record.RecordedAt.Add(ttl),
		FailCount:   1,
		LastError:   record.Error,
		LastAttempt: record.RecordedAt,
	}
}

func (s *service) routeMetricSignals(now time.Time, ttl time.Duration) (map[string]float64, map[string]float64) {
	if s == nil || s.routeHealth == nil {
		return nil, nil
	}
	return s.routeHealth.MetricSignals(now, ttl)
}

package llamaserver

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"

	"github.com/DocumentDrivenDX/fizeau/internal/provider/utilization"
)

// UtilizationProbe queries llama-server observability endpoints and
// normalizes them into the shared endpoint utilization shape.
type UtilizationProbe struct {
	baseURL string
	client  *http.Client
	cache   utilization.Cache
}

// NewUtilizationProbe creates a probe for an OpenAI-compatible llama-server
// base URL.
func NewUtilizationProbe(baseURL string, client *http.Client) *UtilizationProbe {
	if client == nil {
		client = http.DefaultClient
	}
	return &UtilizationProbe{
		baseURL: baseURL,
		client:  client,
	}
}

// Probe first tries /metrics on the server root and falls back to /slots when
// metrics are unavailable.
func (p *UtilizationProbe) Probe(ctx context.Context) utilization.EndpointUtilization {
	if sample, ok := p.probeMetrics(ctx); ok {
		return p.cache.Remember(sample)
	}
	if sample, ok := p.probeSlots(ctx); ok {
		return p.cache.Remember(sample)
	}
	if stale, ok := p.cache.Stale(); ok {
		return stale
	}
	return utilization.Unknown(utilization.SourceLlamaMetrics)
}

func (p *UtilizationProbe) probeMetrics(ctx context.Context) (utilization.EndpointUtilization, bool) {
	body, err := p.get(ctx, utilization.ServerRoot(p.baseURL)+"/metrics")
	if err != nil {
		return utilization.EndpointUtilization{}, false
	}

	processing, ok := utilization.ParsePrometheusMetricValue(body, "llamacpp:requests_processing")
	if !ok {
		return utilization.EndpointUtilization{}, false
	}
	deferred, ok := utilization.ParsePrometheusMetricValue(body, "llamacpp:requests_deferred")
	if !ok {
		return utilization.EndpointUtilization{}, false
	}

	sample := utilization.EndpointUtilization{
		ActiveRequests: utilization.Int(int(processing)),
		QueuedRequests: utilization.Int(int(deferred)),
		Source:         utilization.SourceLlamaMetrics,
	}
	if cacheUsage, ok := utilization.ParsePrometheusMetricValue(body, "llamacpp:kv_cache_usage_ratio"); ok {
		sample.CacheUsage = utilization.Float64(cacheUsage)
	}
	return sample, true
}

func (p *UtilizationProbe) probeSlots(ctx context.Context) (utilization.EndpointUtilization, bool) {
	body, err := p.get(ctx, utilization.ServerRoot(p.baseURL)+"/slots")
	if err != nil {
		return utilization.EndpointUtilization{}, false
	}

	var arrayPayload []map[string]any
	slots := 0
	processing := 0
	if err := json.Unmarshal([]byte(strings.TrimSpace(body)), &arrayPayload); err == nil {
		slots = len(arrayPayload)
		for _, slot := range arrayPayload {
			if isProcessing(slot) {
				processing++
			}
		}
		return p.slotSample(processing, slots), true
	}

	var objectPayload struct {
		Slots     []map[string]any `json:"slots"`
		SlotCount int              `json:"slot_count"`
	}
	if err := json.Unmarshal([]byte(strings.TrimSpace(body)), &objectPayload); err != nil {
		return utilization.EndpointUtilization{}, false
	}
	slots = objectPayload.SlotCount
	if slots == 0 {
		slots = len(objectPayload.Slots)
	}
	for _, slot := range objectPayload.Slots {
		if isProcessing(slot) {
			processing++
		}
	}
	return p.slotSample(processing, slots), true
}

func (p *UtilizationProbe) slotSample(processing, slots int) utilization.EndpointUtilization {
	sample := utilization.EndpointUtilization{
		ActiveRequests: utilization.Int(processing),
		Source:         utilization.SourceLlamaSlots,
	}
	if slots > 0 {
		sample.MaxConcurrency = utilization.Int(slots)
		occupancy := float64(processing) / float64(slots)
		sample.CacheUsage = utilization.Float64(occupancy)
	}
	return sample
}

func isProcessing(slot map[string]any) bool {
	processing, _ := slot["is_processing"].(bool)
	return processing
}

func (p *UtilizationProbe) get(ctx context.Context, endpoint string) (string, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return "", err
	}
	resp, err := p.client.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
		return "", fmt.Errorf("HTTP %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", err
	}
	return string(body), nil
}

