package fizeau

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	"github.com/DocumentDrivenDX/fizeau/internal/modelcatalog"
	"github.com/DocumentDrivenDX/fizeau/internal/routing"
)

var loadRoutingCatalog = modelcatalog.Default

// ResolveRoute resolves an under-specified RouteRequest to a concrete
// (Harness, Provider, Model) decision per CONTRACT-003.
//
// The implementation delegates to internal/routing.Resolve — the single
// routing engine that consolidates DDx-side harness-tier ranking and
// agent-side provider failover ordering.
func (s *service) ResolveRoute(ctx context.Context, req RouteRequest) (*RouteDecision, error) {
	if err := ValidatePowerBounds(req.MinPower, req.MaxPower); err != nil {
		return nil, err
	}
	if err := ValidateRole(req.Role); err != nil {
		return nil, err
	}
	if err := ValidateCorrelationID(req.CorrelationID); err != nil {
		return nil, err
	}
	s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
	cat := serviceRoutingCatalog()
	profile := req.Profile
	if profile == "" {
		profile = reqProfileFromModelRef(cat, req.ModelRef)
	}
	modelRef := reqModelRefStripProfile(cat, req.ModelRef)
	providerPreference, err := providerPreferenceForProfile(cat, profile)

	// service_catalog_cache.go.
	catalog *catalogCache

	// routingQuality records routing-quality observations (ADR-006 §5).
	// Populated by Execute on every request and read by RouteStatus and
	// UsageReport.
	routingQuality *routingQualityStore

	// providerQuota is the per-provider quota state machine. Routing reads
	// the projected exhausted set on every Resolve so quota_exhausted
	// providers are excluded from candidate selection.
	providerQuota *ProviderQuotaStateStore

	// providerBurnRate observes per-provider token consumption against the
	// operator-configured daily_token_budget and pre-emptively transitions
	// providers into quota_exhausted when local burn-rate predicts the
	// budget will be exceeded before the next UTC daily reset.
	providerBurnRate *ProviderBurnRateTracker

	runtime serviceimpl.Runtime
}

const (
	defaultCatalogProbeTimeout   = 2 * time.Second
	defaultCatalogRefreshTimeout = 30 * time.Second
)

func (o ServiceOptions) catalogProbeTimeout() time.Duration {
	if o.CatalogProbeTimeout > 0 {
		return o.CatalogProbeTimeout
	}
	return defaultCatalogProbeTimeout
}

func (o ServiceOptions) catalogRefreshTimeout() time.Duration {
	if o.CatalogRefreshTimeout > 0 {
		return o.CatalogRefreshTimeout
	}
	return defaultCatalogRefreshTimeout
}

func (s *service) now() time.Time {
	return s.runtime.Now()
}

// lastDecisionEntry caches the most recent RouteDecision for a route key.
type lastDecisionEntry struct {
	decision *RouteDecision
	at       time.Time
}

// loadServiceConfig, when non-nil, is called by New to load a ServiceConfig
// from a directory path when opts.ServiceConfig is nil. It is registered by
// the config package via init() to break the import cycle (config imports root).
var loadServiceConfig func(dir string) (ServiceConfig, error)

// RegisterConfigLoader is called by the config package's init() to install the
// config-loading function. Do not call this from application code.
func RegisterConfigLoader(fn func(dir string) (ServiceConfig, error)) {
	loadServiceConfig = fn
}

// New constructs a FizeauService. When opts.ServiceConfig is nil, New attempts to
// load configuration automatically:
//  1. If opts.ConfigPath is non-empty, load from filepath.Dir(opts.ConfigPath).
//  2. Otherwise, load from the default global config location.
//
// Automatic loading requires the config package to be imported somewhere in the
// binary (it registers the loader via init). If the config package is not
// imported and ServiceConfig is nil, the service starts without provider config
// (ListProviders/HealthCheck will return errors until config is injected).
func New(opts ServiceOptions) (FizeauService, error) {
	if opts.ServiceConfig == nil && loadServiceConfig != nil && shouldAutoLoadServiceConfig(opts) {
		dir := ""
		if opts.ConfigPath != "" {
			dir = filepath.Dir(opts.ConfigPath)
		}
		sc, err := loadServiceConfig(dir)
		if err != nil {
			return nil, fmt.Errorf("agent.New: load config: %w", err)
		}
		opts.ServiceConfig = sc
	}
	svc := &service{
		opts:             opts,
		registry:         harnesses.NewRegistry(),
		hub:              newSessionHub(),
		runtime:          serviceimpl.NewRuntime(serviceimpl.RuntimeDeps{}),
		catalog:          newCatalogCache(catalogCacheOptions{AsyncRefreshTimeout: opts.catalogRefreshTimeout()}),
		routeHealth:      routehealth.NewStore(),
		routeLeases:      routehealth.NewLeaseStore(),
		routingQuality:   newRoutingQualityStore(),
		providerQuota:    NewProviderQuotaStateStore(),
		providerBurnRate: NewProviderBurnRateTracker(),
	}
	// Hydrate per-provider daily_token_budget from ServiceConfig so the
	// burn-rate tracker can predict exhaustion before the upstream quota
	// signal arrives.
	if opts.ServiceConfig != nil {
		for _, name := range opts.ServiceConfig.ProviderNames() {
			entry, ok := opts.ServiceConfig.Provider(name)
			if !ok {
				continue
			}
			if entry.DailyTokenBudget > 0 {
				svc.providerBurnRate.SetBudget(name, entry.DailyTokenBudget)
			}
		}
	}
	svc.reapStaleHarnessSessions()
	svc.ensurePrimaryQuotaRefresh(context.Background(), quotaRefreshStartup)
	svc.startPrimaryQuotaRefreshWorker()
	svc.startQuotaRecoveryProbeLoop()
	return svc, nil
}

// harnessType returns "native" for HTTP/embedded harnesses, "subprocess" for CLI-invoked ones.
func harnessType(cfg harnesses.HarnessConfig) string {
	if cfg.IsHTTPProvider || cfg.IsLocal {
		return "native"
	}
	return "subprocess"
}

// supportedPermissions extracts the permission levels from PermissionArgs keys,
// returning them in canonical order.
func supportedPermissions(cfg harnesses.HarnessConfig) []string {
	if len(cfg.PermissionArgs) == 0 {
		return nil
	}
	order := []string{"safe", "supervised", "unrestricted"}

package fizeau

import (
	"strings"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/routehealth"
	"github.com/DocumentDrivenDX/fizeau/internal/routing"
)

const stickyRouteLeaseTTL = routehealth.DefaultLeaseTTL

func (s *service) routeLeaseStore() *routehealth.LeaseStore {
	if s.routeLeases == nil {
		s.routeLeases = routehealth.NewLeaseStore()
	}
	return s.routeLeases
}

func (s *service) applyStickyRouteLease(stickyKey string, decision *RouteDecision) {
	if s == nil || decision == nil || strings.TrimSpace(stickyKey) == "" {
		return
	}
	if decision.Harness != "agent" || decision.Provider == "" {
		return
	}

	now := time.Now().UTC()
	store := s.routeLeaseStore()
	baseProvider, _, _ := splitEndpointProviderRef(decision.Provider)
	if baseProvider == "" {
		baseProvider = decision.Provider
	}
	if baseProvider == "" || decision.Model == "" {
		return
	}

	key := routehealth.NormalizeLeaseKey(stickyKey, baseProvider, decision.Model)
	if lease, ok := store.Live(now, key); ok {
		if candidate, found := stickyLeaseCandidate(decision.Candidates, decision.Harness, baseProvider, decision.Model, lease.Endpoint); found && candidate.Eligible {
			store.Acquire(now, stickyRouteLeaseTTL, key, baseProvider, lease.Endpoint, decision.Model)
			decision.Provider = candidate.Provider
			decision.Endpoint = candidate.Endpoint
			return
		}
		reason := "endpoint disappeared"
		if candidate, found := stickyLeaseCandidate(decision.Candidates, decision.Harness, baseProvider, decision.Model, lease.Endpoint); found {
			reason = candidate.Reason
			if reason == "" {
				reason = "sticky endpoint became ineligible"
			}
		} else if candidate, found := stickyLeaseAnyEndpoint(decision.Candidates, decision.Harness, baseProvider, lease.Endpoint); found {
			reason = candidate.Reason
			if reason == "" {
				reason = "sticky endpoint became ineligible"
			}
		}
		store.Invalidate(now, key, reason)
	}
	if decision.Provider == "" && decision.Endpoint == "" {
		return
	}
	chosenEndpoint := decision.Endpoint
	if chosenEndpoint == "" {
		_, chosenEndpoint, _ = splitEndpointProviderRef(decision.Provider)
	}
	if chosenEndpoint == "" {
		chosenEndpoint = decision.Provider
	}
	if chosenEndpoint == "" {
		return
	}
	store.Acquire(now, stickyRouteLeaseTTL, key, baseProvider, chosenEndpoint, decision.Model)
}

func stickyLeaseCandidate(candidates []RouteCandidate, harness, provider, model, endpoint string) (RouteCandidate, bool) {
	for _, candidate := range candidates {
		if !candidate.Eligible || candidate.Harness != harness || candidate.Model != model {
			continue
		}
		baseProvider, candidateEndpoint, _ := splitEndpointProviderRef(candidate.Provider)
		if baseProvider == "" {
			baseProvider = candidate.Provider
		}
		if baseProvider != provider {
			continue
		}
		if candidateEndpoint == "" {
			candidateEndpoint = candidate.Endpoint
		}
		if candidateEndpoint == endpoint {
			return candidate, true
		}
	}
	return RouteCandidate{}, false
}

func stickyLeaseAnyEndpoint(candidates []RouteCandidate, harness, provider, endpoint string) (RouteCandidate, bool) {
	for _, candidate := range candidates {
		if candidate.Harness != harness {
			continue
		}
		baseProvider, candidateEndpoint, _ := splitEndpointProviderRef(candidate.Provider)
		if baseProvider == "" {
			baseProvider = candidate.Provider
		}
		if baseProvider != provider {
			continue
		}
		if candidateEndpoint == "" {
			candidateEndpoint = candidate.Endpoint
		}
		if candidateEndpoint == endpoint {
			return candidate, true
		}
	}
	return RouteCandidate{}, false
}

func (s *service) routeEndpointLoadsResolver(now time.Time) map[string]routing.EndpointLoad {
	if s == nil {
		return nil
	}
	leaseStore := s.routeLeaseStore()
	utilStore := s.routeUtilizationStore()
	return func(provider, endpoint, model string) (routing.EndpointLoad, bool) {
		leaseCounts := leaseStore.LeaseCounts(now, provider, model)
		loads := utilStore.EndpointLoads(provider, model, leaseCounts)
		load, ok := loads[endpoint]
		if !ok {
			if count, ok := leaseCounts[endpoint]; ok {
				return routing.EndpointLoad{
					LeaseCount:      count,
					NormalizedLoad:  float64(count),
					UtilizationFresh: false,
				}, true
			}
			return routing.EndpointLoad{}, false
		}
		return routing.EndpointLoad{
			LeaseCount:           load.LeaseCount,
			NormalizedLoad:       load.NormalizedLoad,
			UtilizationFresh:     load.UtilizationFresh,
			UtilizationSaturated: load.UtilizationSaturated,
		}, true
	}
}

