 69	// EndpointLoads returns the normalized load per endpoint for provider/model.
 70	// Fresh utilization samples are combined with the supplied lease counts;
 71	// stale or missing samples fall back to lease counts only.
 72	func (s *UtilizationStore) EndpointLoads(provider, model string, leaseCounts map[string]int) map[string]EndpointLoad {
 73		if s == nil {
 74			return nil
 75		}
 76		keyProvider := strings.TrimSpace(provider)
 77		keyModel := strings.TrimSpace(model)
 78	
 79		s.mu.RLock()
 80		defer s.mu.RUnlock()
 81		if len(s.samples) == 0 && len(leaseCounts) == 0 {
 82			return nil
 83		}
 84	
 85		keys := make(map[string]struct{})
 86		for endpoint := range leaseCounts {
 87			keys[endpoint] = struct{}{}
 88		}
 89		for key := range s.samples {
 90			if keyProvider != "" && key.Provider != keyProvider {
 91				continue
 92			}
 93			if keyModel != "" && key.Model != keyModel {
 94				continue
 95			}
 96			if key.Endpoint != "" {
 97				keys[key.Endpoint] = struct{}{}
 98			}
 99		}
100		if len(keys) == 0 {
101			return nil
102		}
103	
104		out := make(map[string]EndpointLoad, len(keys))
105		for endpoint := range keys {
106			leaseCount := leaseCounts[endpoint]
107			load := EndpointLoad{
108				LeaseCount:       leaseCount,
109				NormalizedLoad:   float64(leaseCount),
110				UtilizationFresh: false,
111			}
112			key := NormalizeUtilizationKey(keyProvider, endpoint, keyModel)
113			sample, ok := s.samples[key]
114			if !ok && keyProvider != "" {
115				// Allow provider-wide samples to match when the caller does not
116				// have a fully-qualified endpoint name.
117				sample, ok = s.samples[NormalizeUtilizationKey(keyProvider, "", keyModel)]
118			}
119			if !ok || sample.Freshness != utilization.FreshnessFresh {
120				out[endpoint] = load
121				continue
122			}
123			normalized, saturated := normalizedLoadFromSample(sample)
124			load.NormalizedLoad = float64(leaseCount) + normalized
125			load.UtilizationFresh = true
126			load.UtilizationSaturated = saturated
127			out[endpoint] = load
128		}
129	
130		return out
131	}
