133	func normalizedLoadFromSample(sample utilization.EndpointUtilization) (float64, bool) {
134		var active int
135		var queued int
136		if sample.ActiveRequests != nil {
137			active = *sample.ActiveRequests
138		}
139		if sample.QueuedRequests != nil {
140			queued = *sample.QueuedRequests
141		}
142		if sample.MaxConcurrency != nil && *sample.MaxConcurrency > 0 {
143			total := active + queued
144			pressure := float64(total) / float64(*sample.MaxConcurrency)
145			if pressure < 0 {
146				pressure = 0
147			}
148			return pressure, total >= *sample.MaxConcurrency
149		}
150		if sample.CacheUsage != nil {
151			pressure := *sample.CacheUsage
152			if pressure < 0 {
153				pressure = 0
154			}
155			return pressure, pressure >= 1
156		}
157		total := active + queued
158		if total < 0 {
159			total = 0
160		}
161		return float64(total), false
162	}
163	
164	func cloneUtilization(sample utilization.EndpointUtilization) utilization.EndpointUtilization {
165		out := sample
166		if sample.ActiveRequests != nil {
167			out.ActiveRequests = utilization.Int(*sample.ActiveRequests)
168		}
169		if sample.QueuedRequests != nil {
170			out.QueuedRequests = utilization.Int(*sample.QueuedRequests)
171		}
172		if sample.CacheUsage != nil {
173			out.CacheUsage = utilization.Float64(*sample.CacheUsage)
174		}
175		if sample.MaxConcurrency != nil {
176			out.MaxConcurrency = utilization.Int(*sample.MaxConcurrency)
177		}
178		return out
179	}
