379	// Resolve runs the engine end-to-end and returns a Decision.
380	//
381	// The engine:
382	//  1. Enumerates (harness, provider, model) candidates from inputs.
383	//  2. Applies gating (capability, override, model-pin, surface).
384	//  3. Scores per profile policy with cooldown demotion + perf bias.
385	//  4. Sorts viable → score → cost → locality → name.
386	//  5. Returns the top viable candidate with the full ranked list.
387	//
388	// Returns an error only when no viable candidate exists.
389	func Resolve(req Request, in Inputs) (*Decision, error) {
390		if in.Now.IsZero() {
391			in.Now = time.Now()
392		}
393	
394		canonicalHarness := req.Harness
395		if canonicalHarness == "local" {
396			canonicalHarness = "agent"
397		}
398	
399		var ranked []rankedCandidate
400		for _, h := range in.Harnesses {
401			// TestOnly harnesses (script/virtual) only reachable via explicit override.
402			if h.TestOnly && canonicalHarness != h.Name {
403				continue
404			}
405			// Automatic profile/tier routing is restricted to harnesses with full
406			// coverage. Explicit Harness pins can still use experimental/ad-hoc
407			// harnesses.
408			if canonicalHarness == "" && !h.AutoRoutingEligible {
409				continue
410			}
411			// Hard harness override: skip non-matching harnesses.
412			if canonicalHarness != "" && canonicalHarness != h.Name {
413				continue
414			}
415			entries := buildHarnessCandidates(h, req, in)
416			ranked = append(ranked, entries...)
417		}
418	
419		// Compute scores.
420		for i := range ranked {
421			ranked[i].out.Score = scorePolicy(req.Profile, ranked[i].internal)
422			if ranked[i].out.Eligible {
423				ranked[i].out.Reason = fmt.Sprintf("profile=%s; score=%.1f", req.Profile, ranked[i].out.Score)
424			}
425		}
426		neutralCost, hasKnownCost := neutralKnownCost(ranked)
427	
428		// Sort: eligible first, then descending score, then cost, then locality,
429		// then alphabetical.
430		sort.SliceStable(ranked, func(i, j int) bool {
431			ei, ej := ranked[i].out.Eligible, ranked[j].out.Eligible
432			if ei != ej {
433				return ei
434			}
435			if !ei {
436				return ranked[i].out.Harness < ranked[j].out.Harness
437			}
438			if ranked[i].out.Score != ranked[j].out.Score {
439				return ranked[i].out.Score > ranked[j].out.Score
440			}
441			if hasKnownCost {
442				ci := candidateCostTieValue(ranked[i], neutralCost)
443				cj := candidateCostTieValue(ranked[j], neutralCost)
444				if ci != cj {
445					return ci < cj
446				}
447			}
448			// Locality tiebreak: prefer local cost-class.
449			li := costClassRank[ranked[i].internal.CostClass] == 0
450			lj := costClassRank[ranked[j].internal.CostClass] == 0
451			if li != lj {
452				return li
453			}
454			if sameLocalEndpointGroup(ranked[i].internal, ranked[j].internal) {
455				if ranked[i].internal.EndpointSaturated != ranked[j].internal.EndpointSaturated {
456					return !ranked[i].internal.EndpointSaturated
457				}
458				if ranked[i].internal.EndpointLoad != ranked[j].internal.EndpointLoad {
459					return ranked[i].internal.EndpointLoad < ranked[j].internal.EndpointLoad
460				}

