621	func explicitProfileConstraint(profile, providerPreference string) (string, bool) {
622		switch providerPreference {
623		case ProviderPreferenceLocalOnly:
624			return ProviderPreferenceLocalOnly, true
625		case ProviderPreferenceSubscriptionOnly:
626			return ProviderPreferenceSubscriptionOnly, true
627		}
628		switch profile {
629		case "local", "offline", "air-gapped":
630			return ProviderPreferenceLocalOnly, true
631		case "smart", "code-smart", "code-high":
632			return ProviderPreferenceSubscriptionOnly, true
633		default:
634			return "", false
635		}
636	}
637	
638	func harnessViolatesProfileConstraint(h HarnessEntry, constraint string) bool {
639		switch constraint {
640		case ProviderPreferenceLocalOnly:
641			return !h.IsLocal
642		case ProviderPreferenceSubscriptionOnly:
643			return !h.IsSubscription
644		default:
645			return false
646		}
647	}
648	
649	func modelPinViolatesProfileConstraint(model string, in Inputs, constraint string) bool {
650		var constrainedCanServe bool
651		var outsideCanServe bool
652		for _, h := range in.Harnesses {
653			if h.TestOnly || !h.AutoRoutingEligible {
654				continue
655			}
656			if !harnessCanServeExactModel(h, model) {
657				continue
658			}
659			if harnessViolatesProfileConstraint(h, constraint) {
660				outsideCanServe = true
661			} else {
662				constrainedCanServe = true
663			}
664		}
665		return !constrainedCanServe && outsideCanServe
666	}
