668	func harnessCanServeExactModel(h HarnessEntry, model string) bool {
669		if len(h.SupportedModels) > 0 && harnessSupportsModel(h.SupportedModels, model) {
670			return true
671		}
672		if h.DefaultModel == model {
673			return true
674		}
675		providers := h.Providers
676		if len(providers) == 0 {
677			providers = []ProviderEntry{{Name: ""}}
678		}
679		for _, p := range providers {
680			if p.DefaultModel == model {
681				return true
682			}
683			if len(p.DiscoveredIDs) > 0 && FuzzyMatch(model, p.DiscoveredIDs) != "" {
684				return true
685			}
686		}
687		return false
688	}
