1008	func sameLocalEndpointGroup(a, b candidateInternal) bool {
1009		if a.Harness == "" || b.Harness == "" || a.Model == "" || b.Model == "" {
1010			return false
1011		}
1012		if a.CostClass != "local" || b.CostClass != "local" {
1013			return false
1014		}
1015		aBase := providerBaseName(a.Provider)
1016		bBase := providerBaseName(b.Provider)
1017		if aBase == "" || bBase == "" || aBase != bBase {
1018			return false
1019		}
1020		return a.Model == b.Model
1021	}
